const D = { scale:1, energy:.65, density:.55, speed:1, iso:.5, hue:200, x:.5, y:.5, style:'mercury', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, frc=v=>v-Math.floor(v);
const ss=(a,b,x)=>{ const t=Math.max(0,Math.min(1,(x-a)/(b-a))); return t*t*(3-2*t); };

// coarse buffer
const BW = 176, BH = Math.max(72, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }
const ub = Math.min(BW, BH);

// seed-dependent charge orbits
if (S.seedUsed !== P.seed) {
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.seedUsed = P.seed; S.hoff = fr(1); S.blobs = [];
  for (let i = 0; i < 9; i++) S.blobs.push({
    ph: fr(i*3.1+2)*TAU, sp: .10 + fr(i*5.7+1)*.26, orb: .10 + fr(i*7.3+4)*.26,
    rr: .11 + fr(i*9.1+3)*.06, wob: fr(i*11.7+5)*TAU });
}

const dens = clp(P.density,0,1), en = clp(P.energy,0,1), sc = clp(P.scale,0.25,2.4);
const style = P.style, hoff = S.hoff, sec = K.section|0;
const t = K.t * clp(P.speed,0,4);
const NB = Math.max(3, Math.round(3 + dens*6));
const bass = A.bass||0, rms = A.rms||0, treb = A.treble||0;

// live charge positions in buffer space
const bcx = clp(P.x,0,1)*BW, bcy = clp(P.y,0,1)*BH, eps = (0.032*ub)*(0.032*ub);
const cs = S.blobs;
const px_=[], py_=[], pr_=[];
for (let i = 0; i < NB; i++) {
  const b = cs[i];
  const ang = t*b.sp + b.ph;
  const orbR = b.orb * (0.82 + 0.28*Math.sin(t*0.13 + b.wob) + K.intensity*0.16);
  const ox = bcx + Math.cos(ang)*orbR*ub + Math.sin(t*b.sp*1.7 + b.wob)*ub*0.05;
  const oy = bcy + Math.sin(ang*1.07 + b.ph)*orbR*ub*0.74 + Math.cos(t*b.sp*1.3 + b.wob)*ub*0.05;
  const rad = b.rr*ub*sc * (1 + 0.12*Math.sin(t*b.sp*2 + b.wob) + bass*0.30);
  px_.push(ox); py_.push(oy); pr_.push(rad*rad);
}

// exposure / palette drift
const expo = 0.74 + en*0.72 + K.intensity*0.26 + rms*0.6;
const isoT = (0.60 + clp(P.iso,0,1)*0.95) * (1 - 0.12*K.swell);
const drift = t*0.05 + sec*0.06;
const hbase = (((P.hue%360)+360)%360)/360;
// iq cosine palette
function pal(m, spread, ph) {
  const r = 0.5 + 0.5*Math.cos(TAU*(spread*m + ph + 0.00));
  const g = 0.5 + 0.5*Math.cos(TAU*(spread*m + ph + 0.33));
  const b = 0.5 + 0.5*Math.cos(TAU*(spread*m + ph + 0.66));
  return [r,g,b];
}
// rotating key light
const Lx = Math.cos(t*0.18 + 0.6), Ly = Math.sin(t*0.18 + 0.6)*0.5 - 0.62;
const Ll = Math.hypot(Lx,Ly)||1, lx = Lx/Ll, ly = Ly/Ll;

const g = S.g; g.loadPixels(); const pix = g.pixels;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    let f = 0, Gx = 0, Gy = 0;
    for (let m = 0; m < NB; m++) {
      const ex = i - px_[m], ey = j - py_[m];
      const d2 = ex*ex + ey*ey + eps;
      const inv = pr_[m] / d2;
      f += inv;
      const k = -2*inv/d2; Gx += k*ex; Gy += k*ey;
    }
    const surf = f / isoT;                       // 1 at the iso shell
    const gm = Math.hypot(Gx,Gy) || 1e-6;
    const nx = -Gx/gm, ny = -Gy/gm;              // outward normal
    let spec = nx*lx + ny*ly; spec = spec>0 ? spec*spec*spec*spec : 0;
    const interior = ss(0.62, 1.06, surf);
    const rim = Math.exp(-Math.pow((surf-1.0)*4.2, 2));
    const ripple = 0.5 + 0.5*Math.sin(surf*7.0 + t*0.5);

    let r, gg, b;
    if (style === 'lava') {
      const gr = [0.07, 0.018, 0.006];
      const s2 = Math.min(1.6, surf);
      const cr = Math.min(1, 0.35 + s2*0.9);
      const cg = Math.max(0, s2*0.75 - 0.28);
      const cb = Math.max(0, s2*0.55 - 0.72);
      r = gr[0] + interior*(cr - gr[0]) + rim*0.55;
      gg = gr[1] + interior*(cg - gr[1]) + rim*0.28;
      b = gr[2] + interior*(cb - gr[2]) + rim*0.05;
      r += spec*0.35*interior; gg += spec*0.30*interior; b += spec*0.18*interior;
    } else if (style === 'xray') {
      const rings = Math.exp(-Math.pow((frc(surf*3.2 - drift*2)-0.5)*3.6, 2));
      const glow = rings*(0.55+0.45*ripple) + rim*0.9;
      const wash = interior*0.10;
      r = 0.02 + wash*0.3 + glow*0.18;
      gg = 0.03 + wash*0.9 + glow*1.0;
      b = 0.05 + wash*0.7 + glow*0.72;
    } else if (style === 'oil') {
      const ang = Math.atan2(ny, nx)/TAU + 0.5;
      const c = pal(surf*0.5 + ang*0.9 + drift*1.4, 1.0, hbase);
      const sh = 0.30 + 0.65*ripple;
      const gr = 0.05;
      r = gr + interior*(c[0]*sh - gr) + rim*0.6 + spec*0.5*interior;
      gg = gr + interior*(c[1]*sh - gr) + rim*0.6 + spec*0.5*interior;
      b = gr + interior*(c[2]*sh - gr) + rim*0.7 + spec*0.5*interior;
    } else if (style === 'ink') {
      const tone = 0.30 + 0.55*ripple;
      const gr = 0.14 - 0.05*surf*(surf<1?1:0);
      let v = gr + interior*(tone - gr) + rim*0.5 + spec*0.55*interior;
      r = v*1.0; gg = v*0.99; b = v*0.96;
    } else { // mercury (default) — chrome teal->magenta iso-bands + bright rim/spec
      const c = pal(surf*0.30 + drift, 0.85, 0.52 + hoff*0.25 + hbase*0.4);
      const sh = 0.38 + 0.52*ripple;
      const gr0 = 0.045, gr1 = 0.060, gr2 = 0.085; // dim indigo-teal ground
      const rc = [0.55, 0.92, 1.0];                // cool chrome rim
      r  = gr0 + interior*(c[0]*sh - gr0) + rim*rc[0]*0.75 + spec*0.85*interior;
      gg = gr1 + interior*(c[1]*sh - gr1) + rim*rc[1]*0.75 + spec*0.85*interior;
      b  = gr2 + interior*(c[2]*sh - gr2) + rim*rc[2]*0.75 + spec*0.85*interior;
    }

    r *= expo; gg *= expo; b *= expo;
    // treble sparkle on specular peaks (audio on top, zero-safe)
    if (treb > 0.02) { const sp = spec*interior*treb*0.6; r += sp; gg += sp; b += sp; }

    const o = 4*(j*BW + i);
    pix[o]   = Math.max(0, Math.min(255, r*255));
    pix[o+1] = Math.max(0, Math.min(255, gg*255));
    pix[o+2] = Math.max(0, Math.min(255, b*255));
    pix[o+3] = 255;
  }
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
